@Component("customer-handler")
@ProcessingGroup("customer-processing-group")
public class CustomerEventHandler {
	
	// core constructor
	CustomerEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCustomerEvent
     */
    @EventHandler
    public void handle( CreateCustomerEvent event) {
        entityManager.persist(new Customer(event.getCustomerId(), event.getName(), event.getCustomerCode(), event.getAddress(), event.getEnterprises(), event.getSalesOrders(), event.getCustomerType()));
    }

    /*
     * @param	event UpdateCustomerEvent
     */
    @EventHandler
    public Customer handle( UpdateCustomerEvent event) {
    	entityManager.merge(new Customer(event.getCustomerId(), event.getName(), event.getCustomerCode(), event.getAddress(), event.getEnterprises(), event.getSalesOrders(), event.getCustomerType()));
    }
    
    /*
     * @param	event DeleteCustomerEvent
     */
    @EventHandler
    public void on( DeleteCustomerEvent event) {
    	Customer entity = new Customer();
   
    	// ------------------------------------------
    	// apply the CustomerId
    	// ------------------------------------------
    	entity.setCustomerId( event.getCustomerId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CustomerRepository customerEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CustomerEventHandler.class.getName());

}
